// WF05 — sanitize incoming Error Trigger payload, prep _errors row + Telegram text.
const inp = ($input.first() && $input.first().json) || {};
const exec = inp.execution || {};
const wf   = inp.workflow || {};
const err  = exec.error || {};

const execId   = String(exec.id || '');
const execUrl  = String(exec.url || '');
const node     = String(exec.lastNodeExecuted || '');
const wfId     = String(wf.id || '');
const wfName   = String(wf.name || '');
const errMsg   = String(err.message || '');
const errStack = String(err.stack || '');

// Build raw payload snapshot — useful subset, NOT the whole exec data.
const rawPayload = JSON.stringify({
  execution_id: execId,
  execution_url: execUrl,
  workflow_name: wfName,
  last_node: node,
  error_message: errMsg,
  error_stack: errStack
});

function sanitize(s) {
  let out = String(s == null ? '' : s);
  // JWT-shaped tokens: header.payload.signature, b64url segments.
  out = out.replace(/\beyJ[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\b/g, '<token>');
  // Long base64 blobs (≥80 chars).
  out = out.replace(/\b[A-Za-z0-9+/]{80,}={0,2}\b/g, (m) => '<base64 ' + m.length + ' bytes>');
  // URL query strings → strip to host+path.
  out = out.replace(/(https?:\/\/[^\s?]+)\?[^\s]+/g, '$1');
  return out;
}

function truncate(s, n) {
  if (s.length <= n) return s;
  return s.slice(0, n - 3) + '...';
}

const errorText      = truncate(sanitize(errMsg), 500);
const payloadRedacted = truncate(sanitize(rawPayload), 500);

// Known WF ids — used by Telegram message line.
const WF_NAMES = {
  'DegFDAfq4HhTX2eU': 'WF01 Receive Files',
  '7XllTLmW3Pzchqv6': 'WF02 Extract & Analyze',
  'BgMRQbJP3XWaZrge': 'WF03 Update Sheets & Drive',
  'km6hEXcuWuwbKYxu': 'WF04 Build Archive & Reply'
};
const friendlyWf = WF_NAMES[wfId] || wfName || wfId || 'unknown';

const tgText =
  '\u{1F6A8} P3_bot error\n' +
  'workflow: ' + friendlyWf + '\n' +
  'node: ' + (node || 'n/a') + '\n' +
  'error: ' + truncate(errorText, 200) + '\n' +
  (execUrl ? 'execution: ' + execUrl : 'execution: (no id — trigger-side failure)');

return [{ json: {
  timestamp: new Date().toISOString(),
  session_id: '',
  file_id: '',
  workflow_id: wfId,
  workflow_name: wfName,
  node: node,
  error_text: errorText,
  payload_redacted: payloadRedacted,
  retry_count: 0,
  execution_url: execUrl,
  telegram_text: tgText
}}];
